package com.campusradar.growth;

import com.campusradar.common.ApiProblem;
import com.campusradar.interview.InterviewService;
import org.junit.jupiter.api.*;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.jdbc.core.namedparam.NamedParameterJdbcTemplate;
import org.springframework.jdbc.datasource.*;
import tools.jackson.databind.json.JsonMapper;
import java.util.*;
import static org.junit.jupiter.api.Assertions.*;
import static com.campusradar.growth.PersonalStore.map;

class InterviewSyncTest {
    JdbcTemplate db;PersonalStore store;InterviewService interview;
    @BeforeEach void setup(){var ds=new DriverManagerDataSource("jdbc:h2:mem:interviewsync;MODE=MySQL;DB_CLOSE_DELAY=-1","sa","");db=new JdbcTemplate(ds);db.execute("DROP ALL OBJECTS");String base=",version INT DEFAULT 1,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP";db.execute("CREATE TABLE users(id VARCHAR PRIMARY KEY,status VARCHAR,data_operation VARCHAR,data_revision BIGINT DEFAULT 0)");db.update("INSERT INTO users(id,status,data_operation) VALUES('u1','ACTIVE','IDLE'),('u2','ACTIVE','IDLE')");db.execute("CREATE TABLE applications(id VARCHAR PRIMARY KEY,user_id VARCHAR"+base+")");db.update("INSERT INTO applications(id,user_id) VALUES('a1','u1'),('a2','u2')");db.execute("CREATE TABLE interview_rounds(id VARCHAR PRIMARY KEY,user_id VARCHAR,application_id VARCHAR,title VARCHAR,round_type VARCHAR,sequence INT,mode VARCHAR,status VARCHAR,starts_at TIMESTAMP,ends_at TIMESTAMP,timezone VARCHAR,location VARCHAR,meeting_url VARCHAR"+base+")");db.execute("CREATE TABLE calendar_events(id VARCHAR PRIMARY KEY,user_id VARCHAR,application_id VARCHAR,round_id VARCHAR UNIQUE,title VARCHAR,kind VARCHAR,starts_at TIMESTAMP,ends_at TIMESTAMP,timezone VARCHAR,location VARCHAR,meeting_url VARCHAR,notes VARCHAR,status VARCHAR"+base+")");db.execute("CREATE TABLE interview_reviews(id VARCHAR PRIMARY KEY,user_id VARCHAR,round_id VARCHAR,recording_file_id VARCHAR,transcript VARCHAR,notes VARCHAR,self_score DECIMAL(5,2)"+base+")");db.execute("CREATE TABLE files(id VARCHAR PRIMARY KEY,user_id VARCHAR,purpose VARCHAR,state VARCHAR"+base+")");store=new PersonalStore(new NamedParameterJdbcTemplate(ds),JsonMapper.builder().build(),new DataSourceTransactionManager(ds));interview=new InterviewService(store);}
    Object write(java.util.function.Supplier<Object> action){return store.write("u1",null,"",Map.of(),200,action);}
    Map<String,Object> round(){return map("title","Technical","roundType","TECHNICAL","sequence",1,"mode","ONLINE","status","SCHEDULED","startsAt","2026-11-01T02:00:00Z","endsAt","2026-11-01T03:00:00Z","timezone","Asia/Shanghai","location",null,"meetingUrl",null);}
    @SuppressWarnings("unchecked") @Test void changesFromEitherSideStayInSyncAndDeletingEventUnschedulesRound(){var round=(Map<String,Object>)write(()->interview.roundCreate("u1","a1",round()));String rid=round.get("id").toString();var event=store.all("calendar_events","u1",1,100).getFirst();String eid=event.get("id").toString();write(()->interview.roundPatch("u1",rid,map("version",1,"title","Final tech")));assertEquals("Final tech",store.one("calendar_events","u1",eid).get("title"));write(()->interview.eventPatch("u1",eid,map("version",2,"startsAt","2026-11-02T02:00:00Z","endsAt","2026-11-02T03:00:00Z")));assertEquals("2026-11-02T02:00:00Z",store.one("interview_rounds","u1",rid).get("startsAt"));write(()->{interview.eventDelete("u1",eid,3);return null;});assertNull(store.one("interview_rounds","u1",rid).get("startsAt"));assertEquals(0,store.count("calendar_events","u1"));assertEquals(4L,db.queryForObject("SELECT data_revision FROM users WHERE id='u1'",Long.class));}
    @SuppressWarnings("unchecked") @Test void foreignApplicationAndRecordingCannotBeLinkedAndRoundDeletionCleansPrivateChildren(){assertThrows(ApiProblem.class,()->write(()->interview.roundCreate("u1","a2",round())));var round=(Map<String,Object>)write(()->interview.roundCreate("u1","a1",round()));String rid=round.get("id").toString();db.update("INSERT INTO files(id,user_id,purpose,state) VALUES('f2','u2','RECORDING','READY')");var review=map("version",0,"transcript","Response","notes","Improve","selfScore",80,"recordingFileId","f2");assertThrows(ApiProblem.class,()->write(()->interview.reviewPut("u1",rid,review)));review.put("recordingFileId",null);write(()->interview.reviewPut("u1",rid,review));write(()->{interview.roundDelete("u1",rid,1);return null;});assertEquals(0,db.queryForObject("SELECT COUNT(*) FROM calendar_events",Integer.class));assertEquals(0,db.queryForObject("SELECT COUNT(*) FROM interview_reviews",Integer.class));assertEquals(0,db.queryForObject("SELECT COUNT(*) FROM interview_rounds",Integer.class));}
    @SuppressWarnings("unchecked") @Test void detachedRecordingIsQueuedForErasureOnlyWhenNoOtherReviewReferencesIt(){db.update("INSERT INTO files(id,user_id,purpose,state) VALUES('recording','u1','RECORDING','READY')");var first=(Map<String,Object>)write(()->interview.roundCreate("u1","a1",round()));String r1=first.get("id").toString();var body=map("version",0,"transcript","","notes","","selfScore",null,"recordingFileId","recording");write(()->interview.reviewPut("u1",r1,body));var next=round();next.put("sequence",2);var second=(Map<String,Object>)write(()->interview.roundCreate("u1","a1",next));String r2=second.get("id").toString();write(()->interview.reviewPut("u1",r2,body));write(()->interview.reviewPut("u1",r1,map("version",1,"transcript","","notes","","selfScore",null,"recordingFileId",null)));assertEquals("READY",db.queryForObject("SELECT state FROM files WHERE id='recording'",String.class));write(()->{interview.roundDelete("u1",r2,1);return null;});assertEquals("PENDING_DELETE",db.queryForObject("SELECT state FROM files WHERE id='recording'",String.class));}

    @SuppressWarnings("unchecked") @Test void duplicateSequenceAndAlreadyScheduledRoundAreConflictsWithoutPartialChanges(){var first=(Map<String,Object>)write(()->interview.roundCreate("u1","a1",round()));String r1=first.get("id").toString();var error=assertThrows(ApiProblem.class,()->write(()->interview.roundCreate("u1","a1",round())));assertEquals(409,error.status());var body=round();body.put("sequence",2);var second=(Map<String,Object>)write(()->interview.roundCreate("u1","a1",body));String r2=second.get("id").toString();assertEquals(409,assertThrows(ApiProblem.class,()->write(()->interview.roundPatch("u1",r1,map("version",1,"sequence",2)))).status());var event=store.query("SELECT * FROM calendar_events WHERE round_id=:round",map("round",r1)).getFirst();assertEquals(409,assertThrows(ApiProblem.class,()->write(()->interview.eventPatch("u1",event.get("id").toString(),map("version",1,"roundId",r2)))).status());assertEquals(2,store.count("calendar_events","u1"));assertEquals(1,store.one("interview_rounds","u1",r1).get("sequence"));}

}
